import React, { useState } from 'react';
import './VideoPlayer.css';

const VideoPlayer = () => {
    const [videoFile, setVideoFile] = useState('');
    const [videoSrc, setVideoSrc] = useState('');
    const [videoDimensions, setVideoDimensions] = useState({ width: 0, height: 0 });

    const handleSubmit = (e) => {
        e.preventDefault();
        setVideoSrc(videoFile);
    };

    const handleLoadedMetadata = (e) => {
        const { videoWidth, videoHeight } = e.target;
        setVideoDimensions({ width: videoWidth, height: videoHeight });
    };

    return (
        <div className="video-container" style={{ height: videoDimensions.height ? `${videoDimensions.height}px` : '100vh' }}>
            <form onSubmit={handleSubmit}>
                <input
                    type="text"
                    value={videoFile}
                    onChange={(e) => setVideoFile(e.target.value)}
                    placeholder="Enter video filename"
                />
                <button type="submit">Stream Video</button>
            </form>
            {videoSrc && (
                <video width="100%" controls autoPlay onLoadedMetadata={handleLoadedMetadata}>
                    <source src={videoSrc} type="video/mp4" />
                    Your browser does not support the video tag.
                </video>
            )}
        </div>
    );
};

export default VideoPlayer;
